SELECT w.id AS wallet_trade_id, w.symbol, w.execution_reason, o.id AS sig1m, o.decision AS d1m, pu.id AS used5m, pu.decision AS used5m_decision, pu.original_decision AS used5m_orig, f.id AS newer5m, f.decision AS newer5m_decision, f.original_decision AS newer5m_orig, p.id AS paper_id, p.status, p.close_reason, p.realized_pnl, w.executed_at FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time=o.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN crypto_ai.trade_signal pu ON pu.symbol=o.symbol AND pu.interval_code='5m' AND pu.candle_open_time=o.candle_open_time - INTERVAL 9 MINUTE LEFT JOIN crypto_ai.paper_position p ON p.signal_id=o.id WHERE w.side='BUY' AND w.id IN (112,118,191,214,215,222,237,241,248,255,305,335,348,358,396,405,421) ORDER BY w.executed_at LIMIT 50;